class Invader : Actor() {
    private var direction = 1
    private var frame = 0

    init {
        val sprite = Image()
        sprite.scale(32, 22)
        sprite.setColor(104, 220, 130)
        sprite.fillRect(4, 2, 24, 16)
        sprite.setColor(17, 24, 39)
        sprite.fillRect(9, 7, 4, 4)
        sprite.fillRect(19, 7, 4, 4)
        sprite.setColor(104, 220, 130)
        sprite.fillRect(0, 18, 8, 4)
        sprite.fillRect(24, 18, 8, 4)
        setImage(sprite)
    }

    override fun act() {
        frame += 1
        if (frame % 5 == 0) {
            setLocation(x + direction * 8, y)
            if (x > world.width - 70 || x < 70) direction = -direction
        }
    }
}

class Laser : Actor() {
    init {
        val sprite = Image()
        sprite.scale(4, 14)
        sprite.setColor(255, 230, 90)
        sprite.fillRect(0, 0, 4, 14)
        setImage(sprite)
    }

    override fun act() {
        setLocation(x, y - 8)
        val invader = getOneIntersecting<Invader>()
        if (invader != null) {
            world.removeObject(invader)
            world.removeObject(this)
        } else if (y < 10) {
            world.removeObject(this)
        }
    }
}

class Defender : Actor() {
    private var shotCooldown = 0

    init {
        val sprite = Image()
        sprite.scale(38, 24)
        sprite.setColor(80, 170, 255)
        sprite.fillRect(4, 8, 30, 12)
        sprite.fillRect(12, 2, 14, 8)
        sprite.setColor(220, 240, 255)
        sprite.fillRect(18, 0, 3, 8)
        setImage(sprite)
    }

    override fun act() {
        if (isKeyDown("left")) setLocation(x - 5, y)
        if (isKeyDown("right")) setLocation(x + 5, y)
        if (shotCooldown > 0) shotCooldown -= 1
        if (isKeyDown("space") && shotCooldown == 0) {
            world.addObject(Laser(), x, y - 20)
            shotCooldown = 12
        }
    }
}

class SpaceInvadersWorld : World(720, 480, 1) {
    init {
        setBackground(17, 24, 39)
        var row = 0
        while (row < 4) {
            var column = 0
            while (column < 8) {
                addObject(Invader(), 110 + column * 70, 80 + row * 42)
                column += 1
            }
            row += 1
        }
        addObject(Defender(), 360, 420)
        showText("Move with left/right. Press Space to fire.", 20, 25)
    }

    override fun act() {
        if (getObjects<Invader>().isEmpty()) {
            showText("You win! Press Reset to play again.", 235, 245)
            stop()
        }
    }
}

fun main() {
    val spaceWorld = SpaceInvadersWorld()
    showWorld(spaceWorld)
}
